def check_solution(solution):
    n = 12
    num_edges = n * (n - 1) // 2

    def get_edge_idx(i, j):
        return i * n - i * (i + 1) // 2 + (j - i - 1)

    # Check fixed values
    fixed = {
        7: 0, 9: 0, 23: 1, 27: 0, 28: 0, 29: 0, 33: 1, 34: 0, 39: 1, 40: 0, 53: 0, 58: 0, 63: 0
    }
    for idx, val in fixed.items():
        if solution[idx] != val:
            return False, f"Fixed value mismatch at {idx}: expected {val}, got {solution[idx]}"

    # Check for monochromatic K4
    import itertools
    for combo in itertools.combinations(range(n), 4):
        edges = []
        for i, j in itertools.combinations(combo, 2):
            edges.append(solution[get_edge_idx(i, j)])

        if all(e == 0 for e in edges):
            return False, f"Monochromatic red K4 found at {combo}"
        if all(e == 1 for e in edges):
            return False, f"Monochromatic blue K4 found at {combo}"

    return True, "OK"

